// === Tab: mySketch ===
let hurricanes = [];

// A new class to represent a single hurricane
class Hurricane {
  constructor(x, y) {
    this.tx = random(100); // Start with a random noise value
    this.ty = random(100);
    this.ty2 = random(100);
    this.tx2 = random(100);
    this.locationX = x;
    this.locationY = y;
    this.rad = 10;
  }

  update() {
    // Update the hurricane's location based on noise
    this.locationX = int(map(noise(this.tx), 0, 1, 0, width));
    this.locationY = int(map(noise(this.ty), 0, 1, 200, height));
    this.tx += 0.01;
    this.ty += 0.02;
  }

  display() {
    this.rad = 10;
  // Ensure drawing doesn't go off the top of the canvas
  let startingY = min(this.locationY, height); // Start drawing at the current location or the canvas height, whichever is smaller
  let endingY = max(this.locationY - 400, 0); // End drawing at the current location - 400 or the top of the canvas, whichever is greater

  // Draw ellipses from bottom to top
  for (let y = startingY; y > endingY; y = y - 12) {
    this.pointEllipse(this.locationX, y, this.rad);
    this.rad = this.rad + 2;
    }
  }

  pointEllipse(origox, origoy, r) {
    let weight = random(2, 5);
    strokeWeight(weight);
    stroke(255, 180, 100);

    let r2 = int(random(r - 3, r + 3));
    let origox2 = int(map(noise(this.tx2), 0, 1, origox - 300, origox + 300));
    this.tx2 += 0.01;

    for (let x = 0; x <= 2 * r2; x++) {
      let y = int(sqrt((4 * pow(r2, 2) - pow(x, 2)) / 4));
      let y2 = int(map(noise(this.ty2), 0, 1, y - 7, y + 7));
      this.ty2 += 0.015;

      let xpoint = origox2 + x;
      let xpoint2 = origox2 - x;
      let ypoint = origoy + y2;
      let ypoint2 = origoy - y2;

      point(xpoint, ypoint);
      point(xpoint, ypoint2);
      point(xpoint2, ypoint);
      point(xpoint2, ypoint2);
    }
  }
}

function setup() {
  let canvasHeight = window.innerHeight * 0.8;
  let canvasWidth = (1080 / 1920) * canvasHeight;
  createCanvas(canvasWidth, canvasHeight);
  strokeWeight(1.5);
  frameRate(10);
  background(20, 15, 10);
}

function draw() {
  background(20, 15, 10);
  // Loop through each hurricane in the list and update/draw it
  for (let i = 0; i < hurricanes.length; i++) {
    hurricanes[i].update();
    hurricanes[i].display();
  }
}

function mousePressed() {
  // Create a new Hurricane object at the mouse position
  let newHurricane = new Hurricane((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  // Add the new hurricane to our list
  hurricanes.push(newHurricane);
}

